-- TORVO V2 Row Level Security foundation. UI permissions are not a security boundary.
create or replace function current_app_role() returns text language sql stable security definer set search_path=public as $$select role from app_users where auth_user_id=auth.uid() and active=true limit 1$$;
revoke all on function current_app_role() from public,anon; grant execute on function current_app_role() to authenticated;
create or replace function current_dealer_id() returns uuid language sql stable security definer set search_path=public as $$select d.id from dealers d join app_users u on u.mobile=d.mobile where u.auth_user_id=auth.uid() and u.active=true and u.role='dealer' and d.status='approved' limit 1$$;
revoke all on function current_dealer_id() from public,anon; grant execute on function current_dealer_id() to authenticated;
alter table app_users enable row level security;alter table dealers enable row level security;alter table catalog_items enable row level security;alter table item_rates enable row level security;alter table machine_spare_mapping enable row level security;alter table inventory enable row level security;alter table sales_documents enable row level security;alter table sales_document_lines enable row level security;alter table payments enable row level security;alter table dispatches enable row level security;alter table inventory_movements enable row level security;alter table audit_log enable row level security;
alter table dealer_request_history enable row level security;alter table stock_reorder_requests enable row level security;alter table schemes enable row level security;alter table scheme_slabs enable row level security;alter table dealer_scheme_progress enable row level security;alter table reward_ledger enable row level security;alter table non_available_requests enable row level security;alter table messages enable row level security;alter table notifications enable row level security;alter table app_settings enable row level security;
drop policy if exists app_users_read on app_users;create policy app_users_read on app_users for select to authenticated using(auth_user_id=auth.uid() or current_app_role() in('owner','admin'));
drop policy if exists dealers_read on dealers;create policy dealers_read on dealers for select to authenticated using(current_app_role() in('owner','admin','salesman','accountant','store_keeper') or id=current_dealer_id());
drop policy if exists catalog_read on catalog_items;create policy catalog_read on catalog_items for select to authenticated using(active=true or current_app_role() in('owner','admin'));
drop policy if exists item_rates_read on item_rates;create policy item_rates_read on item_rates for select to authenticated using(current_app_role() in('owner','admin','salesman','accountant'));
drop policy if exists mapping_read on machine_spare_mapping;create policy mapping_read on machine_spare_mapping for select to authenticated using(current_app_role() in('owner','admin','salesman') or(current_app_role()='dealer' and(dealer_visible=true or public_visible=true)));
drop policy if exists inventory_read on inventory;create policy inventory_read on inventory for select to authenticated using(current_app_role() in('owner','admin','store_keeper'));
drop policy if exists sales_documents_read on sales_documents;create policy sales_documents_read on sales_documents for select to authenticated using(current_app_role() in('owner','admin','salesman','accountant') or dealer_id=current_dealer_id());
drop policy if exists sales_lines_read on sales_document_lines;create policy sales_lines_read on sales_document_lines for select to authenticated using(exists(select 1 from sales_documents d where d.id=document_id and(current_app_role() in('owner','admin','salesman','accountant') or d.dealer_id=current_dealer_id())));
drop policy if exists payments_read on payments;create policy payments_read on payments for select to authenticated using(current_app_role() in('owner','admin','accountant') or exists(select 1 from sales_documents d where d.id=estimate_id and d.dealer_id=current_dealer_id()));
drop policy if exists dispatches_read on dispatches;create policy dispatches_read on dispatches for select to authenticated using(current_app_role() in('owner','admin','salesman','store_keeper') or exists(select 1 from sales_documents d where d.id=estimate_id and d.dealer_id=current_dealer_id()));
drop policy if exists inventory_movements_read on inventory_movements;create policy inventory_movements_read on inventory_movements for select to authenticated using(current_app_role() in('owner','admin','store_keeper'));
drop policy if exists audit_log_read on audit_log;create policy audit_log_read on audit_log for select to authenticated using(current_app_role() in('owner','admin'));
drop policy if exists dealer_request_history_read on dealer_request_history;create policy dealer_request_history_read on dealer_request_history for select to authenticated using(current_app_role() in('owner','admin'));
drop policy if exists reorder_read on stock_reorder_requests;create policy reorder_read on stock_reorder_requests for select to authenticated using(current_app_role() in('owner','admin','store_keeper'));
drop policy if exists schemes_read on schemes;create policy schemes_read on schemes for select to authenticated using(current_app_role() in('owner','admin','salesman','dealer'));
drop policy if exists scheme_slabs_read on scheme_slabs;create policy scheme_slabs_read on scheme_slabs for select to authenticated using(current_app_role() in('owner','admin','salesman','dealer'));
drop policy if exists scheme_progress_read on dealer_scheme_progress;create policy scheme_progress_read on dealer_scheme_progress for select to authenticated using(current_app_role() in('owner','admin','salesman') or dealer_id=current_dealer_id());
drop policy if exists reward_read on reward_ledger;create policy reward_read on reward_ledger for select to authenticated using(current_app_role() in('owner','admin') or dealer_id=current_dealer_id());
drop policy if exists non_available_read on non_available_requests;create policy non_available_read on non_available_requests for select to authenticated using(current_app_role() in('owner','admin','salesman') or dealer_id=current_dealer_id());
drop policy if exists messages_read on messages;create policy messages_read on messages for select to authenticated using(current_app_role() in('owner','admin','salesman') or dealer_id=current_dealer_id());
drop policy if exists notifications_read on notifications;create policy notifications_read on notifications for select to authenticated using(user_id in(select id from app_users where auth_user_id=auth.uid()));
drop policy if exists app_settings_read on app_settings;create policy app_settings_read on app_settings for select to authenticated using(current_app_role() in('owner','admin'));
create or replace function get_store_fulfilment_queue() returns table(dispatch_id uuid,estimate_id uuid,dispatch_status text,tracking_code text,stock_deducted_at timestamptz,dealer_id uuid,item_id uuid,qty numeric,item_code text,item_name text,item_type text,brand text,model text) language plpgsql stable security definer set search_path=public as $$declare v_role text;begin select role into v_role from app_users where auth_user_id=auth.uid() and active=true;if v_role not in('owner','admin','store_keeper') then raise exception 'Not authorized';end if;return query select d.id,d.estimate_id,d.status,d.tracking_code,d.stock_deducted_at,s.dealer_id,dl.item_id,dl.qty,c.item_code,c.name,c.item_type,c.brand,c.model from dispatches d join sales_documents s on s.id=d.estimate_id join sales_document_lines dl on dl.document_id=s.id join catalog_items c on c.id=dl.item_id order by d.status,s.created_at;end;$$;
revoke all on function get_store_fulfilment_queue() from public,anon;grant execute on function get_store_fulfilment_queue() to authenticated;
-- No direct INSERT/UPDATE/DELETE policies: reviewed RPCs are the mutation boundary.
